long searchArray::get_travel_time(const army* current_army, long hex)
{
    pathCell* cell = cellData == 0 ? 0 : &cellData[hex];
    long speed = current_army->GetSpeed();
    long turns = (cell->cost + speed - 1) / speed;

    if (turns < 1)
        turns = 1;
    return turns;
}

